import numpy as np

def problem(x: np.ndarray) -> float:
    if x.ndim != 1 or x.shape[0] != 2:
        raise ValueError("Input x must be a 1D NumPy array of shape (2,)")

    x = np.asarray(x)
    x1 = x[0] + 1
    x2 = x[1] - 2

    term1 = (1 - x1)**2 + 100 * (x2 - x1**2)**2 #shifted Rosenbrock

    sigma = 4
    term2 = np.exp(-np.sum((x/sigma)**2)) #gaussian envelope

    term3 = 0.1 * np.arcsinh(np.prod(x)) # arsinh of product

    if np.sum(x) > 0:
        term4 = 0.05 * (x1**2 + x2**2)
    else:
        term4 = -0.01 * (x1**2 + x2**2)

    return float(term1 * term2 + term3 + term4)

import numpy as np

def problem(x: np.ndarray) -> float:
    if x.ndim != 1 or x.shape[0] != 2:
        raise ValueError("Input x must be a 1D NumPy array of shape (2,)")

    x = np.asarray(x)
    x = x + 0.5 #shifting the domain to avoid some undefined behaviour in arcsinh
    a = 10
    term1 = a * 2 + np.sum(x**2 - a * np.cos(2 * np.pi * x)) + np.sum(x) * 0.1 #rastrigin with bias term
    sigma = 3
    term2 = np.exp(-np.sum((x/sigma)**2)**0.75) # gaussian decay

    if np.sum(x) > 0:
        term3 = 0.05 * np.arcsinh(np.prod(x)*np.sqrt(np.abs(np.sum(x)))) * (1 / (1 + np.exp(-np.prod(x)))) * (x[0] / (x[1] + 1e-6))# add some complex nonlinearity depending of input scaled by sigmoid and an input ratio
    else:
        term3 = 0
    return float(term1 * term2 + term3)

import numpy as np

def problem(x: np.ndarray) -> float:
    if x.ndim != 1 or x.shape[0] != 2:
        raise ValueError("Input x must be a 1D NumPy array of shape (2,)")

    x = np.asarray(x)
    a = 10
    term1 = a * 2 + np.sum(x**2 - a * np.cos(2 * np.pi * x)) + np.sum(x) * 0.1 #rastrigin with bias term
    sigma = 3
    term2 = np.exp(-np.sum((x/sigma)**2)**0.75)  # gaussian decay

    term3 = 0.05 * np.arcsinh(np.prod(x)) * np.exp(-(x[0] - x[1])**2 / 10) # modified arcsinh interaction

    magnitude = np.sum(np.abs(x))

    if magnitude == 0:
        term4 = 0.0  # avoid division by zero
    else:
        term4 = np.sinc(magnitude) * (x[0] + x[1]) * 0.1

    return float(term1 * term2 + term3 + term4)

import numpy as np

def problem(x: np.ndarray) -> float:
    if x.ndim != 1 or x.shape[0] != 2:
        raise ValueError("Input x must be a 1D NumPy array of shape (2,)")

    x = np.asarray(x)
    a = 10
    term1 = a * 2 + np.sum(x**2 - a * np.cos(2 * np.pi * x)) + np.sum(x) * 0.1
    sigma = 3
    term2 = np.exp(-np.sum(((x-1)/sigma)**2)**0.75)

    if np.sum(x) > 0:
        term3 = 0.05 * np.arcsinh(np.prod(x))
    else:
        term3 = 0

    term4 = 0.01*np.tanh(np.sum(x**2))
    return float(term1 * term2 + term3 + term4)

import numpy as np

def problem(x: np.ndarray) -> float:
    if x.ndim != 1 or x.shape[0] != 2:
        raise ValueError("Input x must be a 1D NumPy array of shape (2,)")

    x = np.asarray(x)
    a = 20
    b = 0.2
    c = 2 * np.pi
    term1 = -a * np.exp(-b * np.sqrt(0.5 * np.sum(x**2))) - np.exp(0.5 * np.sum(np.cos(c * x))) + a + np.exp(1) + np.sum(x) * 0.05 # Ackley with bias

    term2 = (1 - x[0])**2 + 100 * (x[1] - x[0]**2)**2  # Rosenbrock

    if np.prod(x) > 0:
        term3 = 0.1 * np.sin(np.sum(x**3))
    else:
        term3 = 0

    return float(term1 * (1 / (1 + term2 * 0.01)) + term3)

import numpy as np

def problem(x: np.ndarray) -> float:
    if x.ndim != 1 or x.shape[0] != 2:
        raise ValueError("Input x must be a 1D NumPy array of shape (2,)")

    x = np.asarray(x)
    a = 10
    term1 = a * 2 + np.sum(x**2 - a * np.cos(2 * np.pi * x)) + np.sum(x) * 0.1
    sigma = 3
    term2 = np.exp(-np.sum((x/sigma)**2)**0.75)

    if np.sum(x) > 0:
        term3 = 0.05 * np.arcsinh(np.prod(x))
    else:
        term3 = 0

    term4 = 0.1 * np.sin(np.sum(np.abs(x + 1)**1.5)) - 0.05 # shifted + scaled for better integration

    return float(term1 * term2 + term3 + term4)

