import numpy as np

def problem(x: np.ndarray) -> float:
    if x.ndim != 1 or x.shape[0] != 2:
        raise ValueError("Input x must be a 1D NumPy array of shape (2,)")

    x = np.asarray(x)
    x = x + 1 # Shifting the function
    a = 1.0
    b = 100.0
    term1 = (a - x[0])**2 + b * (x[1] - x[0]**2)**2  # Rosenbrock function

    sigma = 3
    term2 = np.exp(-np.sum((x/sigma)**2)**0.5)  # Gaussian Decay

    if x[0] > x[1]:
        term3 = 0.2 * np.exp(x[0] - x[1]) # Conditional Exponential Skewness
    else:
        term3 = 0

    def sinc(x):
        if abs(x) < 1e-6:
            return 1.0
        else:
            return np.sin(x) / x
    term4 = 0.1*np.prod([sinc(5*xi) for xi in x]) # Sinc based ruggedness

    return float(term1 * term2 + term3+ term4)

